package com.bank.tfmod;

import java.util.*;
import java.util.logging.Logger;

// A reusable module: same logic, parameterized by inputs, producing outputs.
public class Module {
    private static final Logger log = Logger.getLogger(Module.class.getName());
    private final String name;
    private final Map<String,Object> outputs = new LinkedHashMap<>();

    public Module(String name) { this.name = name; }

    // "Render" the module with inputs; records outputs other modules can consume.
    public Map<String,Object> instantiate(String env, Map<String,Object> inputs) {
        log.info(() -> "module '" + name + "' [" + env + "] inputs=" + inputs);
        if ("network".equals(name)) {
            outputs.put("subnet_ids", List.of(env + "-subnet-a", env + "-subnet-b"));
        } else if ("eks".equals(name)) {
            outputs.put("node_group", env + "-bank-ng(" + inputs.get("node_count")
                    + "x" + inputs.get("instance_type") + ")");
        }
        return new LinkedHashMap<>(outputs);
    }
}
