package com.bank.tfmod;

import java.util.*;
import java.util.logging.Logger;

// A thin per-environment root: own state key, composes shared modules with env inputs.
public class EnvironmentRoot {
    private static final Logger log = Logger.getLogger(EnvironmentRoot.class.getName());
    private final String env; private final String stateKey;

    public EnvironmentRoot(String env) { this.env = env; this.stateKey = env + "/terraform.tfstate"; }

    public Map<String,Object> apply(int nodeCount, String instanceType, String cidr) {
        log.info(() -> "root[" + env + "] state=" + stateKey + " (isolated per environment)");
        Module network = new Module("network");
        Map<String,Object> net = network.instantiate(env, Map.of("cidr", cidr));
        Module eks = new Module("eks");
        Map<String,Object> result = eks.instantiate(env, Map.of(
                "node_count", nodeCount, "instance_type", instanceType, "subnet_ids", net.get("subnet_ids")));
        log.info(() -> "root[" + env + "] applied -> " + result.get("node_group"));
        return result;
    }
    public String env() { return env; }
}
