package com.bank.tfmod;

import java.math.BigDecimal;
import java.util.logging.*;

public class ModuleDemo {
    private static final Logger log = Logger.getLogger(ModuleDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // Same shared modules, three thin roots with env-specific inputs + isolated state
        new EnvironmentRoot("dev").apply(2, "t3.medium", "10.1.0.0/16");
        new EnvironmentRoot("staging").apply(4, "m5.large", "10.2.0.0/16");
        EnvironmentRoot prod = new EnvironmentRoot("prod");
        prod.apply(10, "m5.2xlarge", "10.0.0.0/16");

        // Prod cluster now backs a real transfer
        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS on prod cluster from shared eks module");
    }
}
